import{At as e,Mt as t,Qt as n,lt as r}from"./chunks/framework.DwOUwJQP.js";var i=JSON.parse(`{"title":"maven命令","description":"","frontmatter":{"title":"maven命令","date":"2020-11-26T19:24:35.000Z","tags":["java"]},"headers":[],"relativePath":"blogs/java/framework/maven命令.md","filePath":"blogs/java/framework/maven命令.md","lastUpdated":1787477097000}`),a={name:`blogs/java/framework/maven命令.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h4 id="maven-命令" tabindex="-1">Maven 命令 <a class="header-anchor" href="#maven-命令" aria-label="Permalink to “Maven 命令”">​</a></h4><h5 id="查看maven的版本及配置信息" tabindex="-1">查看maven的版本及配置信息 <a class="header-anchor" href="#查看maven的版本及配置信息" aria-label="Permalink to “查看maven的版本及配置信息”">​</a></h5><p><code>mvn -version</code></p><h5 id="构建java项目" tabindex="-1">构建java项目 <a class="header-anchor" href="#构建java项目" aria-label="Permalink to “构建java项目”">​</a></h5><p><code>mvn archetype:create -DgroupId= DartifactId= </code></p><h5 id="创建web项目" tabindex="-1">创建web项目 <a class="header-anchor" href="#创建web项目" aria-label="Permalink to “创建web项目”">​</a></h5><p><code>mvn archetype:create -DgroupId= DartifactId= -DarchetypeArtifactId=maven-archetype-webapp </code></p><h5 id="编译项目代码" tabindex="-1">编译项目代码 <a class="header-anchor" href="#编译项目代码" aria-label="Permalink to “编译项目代码”">​</a></h5><p><code>mvn compile</code></p><h5 id="打包项目" tabindex="-1">打包项目 <a class="header-anchor" href="#打包项目" aria-label="Permalink to “打包项目”">​</a></h5><p><code>mvn package</code></p><h5 id="打包项目时跳过单元测试" tabindex="-1">打包项目时跳过单元测试 <a class="header-anchor" href="#打包项目时跳过单元测试" aria-label="Permalink to “打包项目时跳过单元测试”">​</a></h5><p><code>mvn package -Dmaven.test.skip=true </code></p><h5 id="清除编译生成的target文件夹内容" tabindex="-1">清除编译生成的target文件夹内容 <a class="header-anchor" href="#清除编译生成的target文件夹内容" aria-label="Permalink to “清除编译生成的target文件夹内容”">​</a></h5><p><code>mvn clean</code> ,可以配合相应命令使用 如 mvn clean package, mvn clean test</p><h5 id="打包后将其安装在本地仓库" tabindex="-1">打包后将其安装在本地仓库 <a class="header-anchor" href="#打包后将其安装在本地仓库" aria-label="Permalink to “打包后将其安装在本地仓库”">​</a></h5><p><code>mvn install</code></p><h5 id="打包后将其安装到pom文件中配置的远程仓库" tabindex="-1">打包后将其安装到pom文件中配置的远程仓库 <a class="header-anchor" href="#打包后将其安装到pom文件中配置的远程仓库" aria-label="Permalink to “打包后将其安装到pom文件中配置的远程仓库”">​</a></h5><p><code>mvn deploy</code></p><h5 id="显示所有已经解析的所有依赖" tabindex="-1">显示所有已经解析的所有依赖 <a class="header-anchor" href="#显示所有已经解析的所有依赖" aria-label="Permalink to “显示所有已经解析的所有依赖”">​</a></h5><p><code>mvn dependency:list</code></p><h5 id="以树形结构展示项目中的依赖" tabindex="-1">以树形结构展示项目中的依赖 <a class="header-anchor" href="#以树形结构展示项目中的依赖" aria-label="Permalink to “以树形结构展示项目中的依赖”">​</a></h5><p><code>mvn dependency:tree</code></p><h5 id="对项目中的依赖进行分析-依赖未使用-使用但未引入" tabindex="-1">对项目中的依赖进行分析,依赖未使用,使用但未引入 <a class="header-anchor" href="#对项目中的依赖进行分析-依赖未使用-使用但未引入" aria-label="Permalink to “对项目中的依赖进行分析,依赖未使用,使用但未引入”">​</a></h5><p><code>mvn dependency:analyze</code></p><h5 id="生成站点目录" tabindex="-1">生成站点目录 <a class="header-anchor" href="#生成站点目录" aria-label="Permalink to “生成站点目录”">​</a></h5><p><code>mvn site </code></p>`,27)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};